        public void AddCallbacks(ITransformationActions instance)
        {
            if (instance == null || m_Wrapper.m_TransformationActionsCallbackInterfaces.Contains(instance)) return;
            m_Wrapper.m_TransformationActionsCallbackInterfaces.Add(instance);
            @Clocksiniester.started += instance.OnClocksiniester;
            @Clocksiniester.performed += instance.OnClocksiniester;
            @Clocksiniester.canceled += instance.OnClocksiniester;
            @Birdbot.started += instance.OnBirdbot;
            @Birdbot.performed += instance.OnBirdbot;
            @Birdbot.canceled += instance.OnBirdbot;
        }

        /// <summary>
        /// Removes <see cref="InputAction.started"/>, <see cref="InputAction.performed"/> and <see cref="InputAction.canceled"/> callbacks provided via <param cref="instance" /> on all input actions contained in this map.
        /// </summary>
        /// <remarks>
        /// Calling this method when <paramref name="instance" /> have not previously been registered has no side-effects.
        /// </remarks>
        /// <seealso cref="TransformationActions" />
        private void UnregisterCallbacks(ITransformationActions instance)
        {
            @Clocksiniester.started -= instance.OnClocksiniester;
            @Clocksiniester.performed -= instance.OnClocksiniester;
            @Clocksiniester.canceled -= instance.OnClocksiniester;
            @Birdbot.started -= instance.OnBirdbot;
            @Birdbot.performed -= instance.OnBirdbot;
            @Birdbot.canceled -= instance.OnBirdbot;
        }

        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="TransformationActions.UnregisterCallbacks(ITransformationActions)" />.
        /// </summary>
        /// <seealso cref="TransformationActions.UnregisterCallbacks(ITransformationActions)" />
        public void RemoveCallbacks(ITransformationActions instance)
        {
            if (m_Wrapper.m_TransformationActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="TransformationActions.AddCallbacks(ITransformationActions)" />
        /// <seealso cref="TransformationActions.RemoveCallbacks(ITransformationActions)" />
        /// <seealso cref="TransformationActions.UnregisterCallbacks(ITransformationActions)" />
        public void SetCallbacks(ITransformationActions instance)
        {
            foreach (var item in m_Wrapper.m_TransformationActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_TransformationActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
